(() => {
'use strict';
const U=window.DW_UI,V=window.DW_VIEWS,DS=window.DW_DESIGN_STATE,A=DS.authoring,API=window.DW_AUTHORING.api,clone=v=>JSON.parse(JSON.stringify(v)),now=()=>Date.now();
const {esc,icon,pill,notice,table,btn,shell}=U;
const button=(text,action,kind='',disabled=false,attrs='')=>'<button type="button" class="btn '+kind+'" data-au-action="'+action+'" '+(disabled?'disabled':'')+' '+attrs+'>'+esc(text)+'</button>';
const field=(text,value,name,options,disabled=false)=>'<label class="field"><span class="field-label">'+text+'</span>'+(options?'<select data-au-field="'+name+'" '+(disabled?'disabled':'')+'> '+options.map(x=>'<option '+(x===value?'selected':'')+'>'+esc(x)+'</option>').join('')+'</select>':'<input data-au-field="'+name+'" value="'+esc(value)+'" '+(disabled?'disabled':'')+'> ')+'</label>';
const panel=(title,body,extra='')=>'<section class="panel au-panel"><div class="panel-head"><span>'+title+'</span>'+extra+'</div><div class="panel-body stack">'+body+'</div></section>';
const feedback=x=>x.error?notice(x.error,'','red'):x.message?notice(x.message,'',x.result?'green':'blue'):'';
const scopes={inputs:'流程输入',local:'当前调用',shared:'运行共享',previous:'上一步结果',outputs:'调用输出'};
function page(s,body,actions='',active='workspace',subtitle='个人自动化'){return shell(s,'<main class="page au-page"><header class="au-heading"><div><div class="au-eyebrow">'+subtitle+'</div><h2>'+s.title+'</h2></div><div class="row">'+actions+'</div></header>'+body+'</main>',{active});}
const metric=(label,value,sub='')=>'<div class="au-metric"><span>'+label+'</span><strong>'+value+'</strong><small>'+sub+'</small></div>';
function variablesView(s){const v=A.variables,p=v.page,expired=v.snapshot&&now()>=Date.parse(v.snapshot.expiresAt),labels={month:'月份',downloadCount:'下载数量',ready:'已就绪',accessToken:'访问凭据',summary:'摘要',selectedBranch:'所选分支',rows:'报表明细',previousCapture:'上次截图',completed:'已完成',matchCount:'匹配数量'},types={string:'文本',number:'数字',boolean:'布尔值',array:'数组',object:'对象',null:'空值'};const value=x=>x.visibility==='redacted'?'<span class="au-redacted">'+icon('lock',13)+'敏感内容已隐藏</span>':x.visibility==='unavailable'?'<span class="muted">未捕获此值</span>':x.valueResource?pill((x.valueResource.length/1024).toFixed(1)+' KiB','blue')+button('查看','var-resource','small'):esc(typeof x.value==='object'?JSON.stringify(x.value):String(x.value));return page(s,'<div class="au-metrics">'+metric('运行状态',v.runState==='paused'?'已暂停':'运行中','月度报表下载 · 版本 12')+metric('查看范围',scopes[v.scope],v.frameId==='frame-main'?'主流程':'校验下载结果')+metric('读取时点',p?p.snapshotAt.slice(11,19):'尚未读取',expired?'快照已过期':'固定快照 · 有效 60 秒')+'</div><div class="au-columns"><div class="stack">'+panel('变量与值','<div class="au-tabs">'+Object.entries(scopes).map(([k,t])=>button(t,'var-scope',v.scope===k?'active':'',false,'data-au-scope="'+k+'"')).join('')+'</div>'+(v.changed?notice('运行数据已有更新','当前页保持原快照；重新读取后查看新值。','amber'):'')+(p?table(['变量','类型','值'],p.items.map(x=>[esc(labels[x.name]||x.name),types[x.valueType],value(x)])):'<div class="au-empty">'+icon('list',30)+'<strong>选择调用与范围后读取变量</strong><span>运行保持当前状态。</span></div>')+(v.resourceValue?'<div class="au-resource-preview">'+table(['月份','金额'],v.resourceValue.slice(0,5).map(x=>[esc(x.month),String(x.amount)]))+'<small>显示前 5 项，共 '+v.resourceValue.length+' 项</small></div>':'')+'<div class="between"><span class="muted">'+(p?'本页 '+p.items.length+' 项 · 共 '+p.total+' 项':'尚未查询')+'</span>'+button('下一页','var-next','',expired||!p?.nextCursor)+'</div>'+feedback(v),pill(expired?'已过期':p?'已读取':'未读取',expired?'amber':'blue'))+'</div>'+panel('检查上下文',field('调用',v.frameId==='frame-main'?'主流程':'校验下载结果','var-frame',['主流程','校验下载结果'])+table(['项目','当前选择'],[['流程','月度报表下载'],['固定版本','12'],['变量范围',scopes[v.scope]],['数据更新',!p?'尚未读取':v.changed?'有新值':'与读取时点一致']])+button(expired?'重新读取':'读取快照','var-read','primary')+notice('敏感值保持遮蔽','输入凭据及其派生结果不会显示原值。'))+'</div>',btn('返回运行','run-paused'),'runs','运行 / 调试');}
function revisionsView(s){const r=A.revisions,expired=now()>=Date.parse(r.snapshot.expiresAt);return page(s,'<div class="au-columns"><div class="stack">'+panel('已保存版本',r.page.items.map(x=>'<button type="button" class="au-revision '+(r.selected===x.revision?'selected':'')+'" data-au-action="revision-select" data-au-revision="'+x.revision+'"><span class="au-revision-mark">'+icon('history',18)+'</span><span><strong>版本 '+x.revision+'</strong><small>'+x.createdAt.replace('T',' ').slice(0,16)+' · '+x.name+'</small></span>'+ (x.revision==='12'?pill('当前','blue'):'')+'</button>').join('')+'<div class="between"><span class="muted">按保存时间从新到旧</span>'+button('下一页','revision-next','',expired||!r.page.nextCursor)+'</div>'+feedback(r),pill(expired?'查询已过期':'固定查询','blue'))+'</div>'+panel('版本详情',table(['项目','所选版本'],[['流程','月度报表下载'],['版本',r.selected],['当前版本','12'],['打开方式','保留当前草稿，另行查看固定版本']])+button('查看所选版本','revision-open','primary',expired)+button('重新查询','revision-read')+(r.opened?notice('正在查看版本 '+r.opened,'当前草稿保留在制作工作台。','green'):'')+btn('比较参数变化','version-diff'))+'</div>',btn('返回制作工作台','editor-graph'),'workspace','流程 / 历史版本');}
function connectionsView(s){const c=A.connections;return page(s,panel('已保存连接',c.page.items.map(x=>'<div class="au-connection">'+U.square('connect')+'<div><strong>'+esc(x.name)+'</strong><p>'+esc(x.endpoint)+'</p><small>'+esc(x.model)+' · 版本 '+x.version+' · '+(x.credentialPresent?'已保存凭据':'无凭据')+'</small></div>'+button('编辑并测试','connection-open','',false,'data-au-connection="'+x.connectionId+'"')+'</div>').join('')+'<div class="between"><span class="muted">选择连接可修改配置或测试连接。</span><div class="row">'+button('重新查询','connection-read')+button('下一页','connection-next','',!c.page.nextCursor)+'</div></div>'+feedback(c)),btn('返回连接设置','settings-connections'),'settings','设置 / 模型连接');}
function testView(s){const t=A.test,done=t.result,stages=[['配置检查',done?done.configurationValid:null],['连接服务',done?done.reachable:null],['模型响应',done?done.modelAvailable:null]];return page(s,'<div class="au-columns"><div class="stack">'+panel('当前编辑内容',field('服务地址',t.draft.endpoint,'test-endpoint')+field('模型',t.draft.model,'test-model')+table(['参数','值'],[['图像编码','图像地址'],['输出上限','1,024 tokens'],['凭据',t.draft.credential.mode==='saved'?'使用已保存凭据':'本次测试无需凭据']])+'<div class="row">'+button('测试连接','test-start','primary',t.status==='testing')+button('取消测试','test-cancel','',t.status!=='testing')+'</div>'+feedback(t),pill(JSON.stringify(t.draft)===JSON.stringify(t.saved)?'与已保存配置一致':'未保存草稿','amber'))+panel('已保存配置',table(['项目','已保存内容'],[['服务地址',esc(t.saved.endpoint)],['模型',esc(t.saved.model)],['版本',String(t.savedVersion)]]))+'</div>'+panel('测试结果',stages.map(([label,passed],i)=>'<div class="au-check"><span class="au-step '+(passed===true?'done':'')+'">'+(passed===true?'✓':String(i+1))+'</span><div><strong>'+label+'</strong><small>'+(passed===null?(t.status==='testing'?'正在检查':'等待测试'):passed?'通过':'未通过')+'</small></div>'+pill(passed===null?'未完成':passed?'通过':'失败',passed===null?'':passed?'green':'amber')+'</div>').join('')+button('保存当前配置','test-save','primary',t.status==='testing'))+'</div>',btn('连接清单','connection-browser'),'settings','设置 / 未保存连接测试');}
function editView(s){const e=A.edit,isImage=e.kind==='image',preview=isImage?'<div class="au-pixel-canvas"><div class="au-pixel-source"><img src="fixtures/edit-source.png" alt="下载按钮来源图像"><div class="au-pixel-roi"></div></div><span>700% · 原始像素 64 × 32</span></div>':'<div class="au-timeline"><div class="between"><span>0 ms</span><span>2 ms</span><span>4 ms</span></div><div class="au-track"><span>Ctrl 左</span><i style="left:18%;width:39%"></i></div><div class="au-track"><span>S 键</span><i style="left:30%;width:47%"></i></div><div class="au-track"><span>鼠标移动</span><i style="left:40%;width:27%"></i></div></div>';return page(s,'<div class="au-columns"><div class="stack">'+panel('编辑内容预览','<div class="au-tabs">'+button('图像模板','edit-kind',isImage?'active':'',e.saving,'data-au-kind="image"')+button('输入轨迹','edit-kind',!isImage?'active':'',e.saving,'data-au-kind="trajectory"')+'</div>'+preview+table(['编辑项','结果'],isImage?[['裁剪范围','从 (8, 8) 到 (40, 24)'],['输出尺寸','32 × 16 px'],['格式','PNG']]:[['保留时长','4 ms'],['输入配对','已修复并保留完整配对'],['坐标模式','事件坐标']]))+feedback(e)+'</div>'+panel('保存目标',field('保存方式',e.destination==='create'?'创建独立资产':'追加新版本','edit-destination',['追加新版本','创建独立资产'],e.saving)+(e.destination==='create'?field('资产名称',e.name,'edit-name',null,e.saving):table(['目标','当前状态'],[['资产',isImage?'下载按钮':'归档快捷操作'],['当前版本',e.currentVersion],['保存后','保留原版本与现有引用']]))+'<div class="au-divider"></div>'+table(['保存内容','状态'],[['内容',isImage?'裁剪后的图像':'编辑后的输入轨迹'],['保存状态',e.result?'已保存':e.saving?'正在保存':e.error?'保存失败':'尚未保存']])+'<div class="row">'+button(e.error?'重新保存':'保存资产','edit-submit','primary',e.saving||!!e.result)+button('取消保存','edit-cancel','',!e.saving)+'</div>'+(e.result?notice('版本 '+e.result.assetVersion+' 已保存',e.destination==='create'?'已创建独立资产。':'原版本与现有流程绑定继续保留。','green'):''))+'</div>',btn('返回资产库','assets'),'assets','资产 / 手工编辑');}
function contentView(s){
 const c=A.content,percent=Math.round(c.offset/c.raw.length*100),done=c.stage==='saved';
 const stage=done?'已保存':c.saving?'正在保存':c.stage==='failed'?'保存失败':'尚未保存';
 return page(s,'<div class="au-metrics">'+metric('流程内容',(c.raw.length/1048576).toFixed(2)+' MiB',esc(c.model.definition.name))+metric('保存进度',percent+'%',done?'版本 13':c.saving?'正在处理当前草稿':'准备保存当前草稿')+metric('保存状态',stage,done?'可从历史版本查看':'当前草稿保留')+'</div><div class="au-columns"><div class="stack">'+panel('保存进度','<div class="au-save-stages">'+['准备','传输','检查','保存'].map((t,i)=>'<div class="'+((i===0||i===1&&c.offset>0||i===2&&c.ref||i===3&&done)?'complete':'')+'"><span>'+String(i+1)+'</span><strong>'+t+'</strong></div>').join('')+'</div><div class="au-progress"><i style="width:'+percent+'%"></i></div><div class="between"><span>已传输 '+(c.offset/1024).toFixed(0)+' KiB</span><span>共 '+(c.raw.length/1024).toFixed(0)+' KiB</span></div>'+feedback(c))+'</div>'+panel('流程与版本',table(['项目','本次保存'],[['流程',esc(c.model.definition.name)],['当前版本',c.baseRevision],['保存内容','当前编辑的流程'],['保存结果',done?'版本 13':stage]])+'<div class="row">'+button(c.stage==='failed'?'重新保存':'保存流程','content-submit','primary',c.saving||done)+button('取消保存','content-cancel','',!c.saving&&!['uploading','sealed'].includes(c.stage))+'</div>'+btn('返回制作工作台','editor-graph'))+'</div>',btn('返回流程','editor-graph'),'workspace','流程 / 版本保存');
}
function currentState(){return A.current.startsWith('variables')?A.variables:A.current.startsWith('revision')?A.revisions:A.current==='connection-browser'?A.connections:A.current.startsWith('connection')?A.test:A.current.startsWith('asset')?A.edit:A.content;}
const handlers={
 'var-resource':()=>API.readVariableResource(),'var-read':()=>API.readVariables(),'var-next':()=>API.variablesNext(),'var-scope':el=>{A.variables.scope=el.dataset.auScope;API.readVariables();},
 'revision-read':()=>API.readRevisions(),'revision-next':()=>{A.revisions.offset+=3;return API.readRevisions(false);},'revision-select':el=>{A.revisions.selected=el.dataset.auRevision;},'revision-open':()=>{if(now()>=Date.parse(A.revisions.snapshot.expiresAt))throw Error('历史查询已过期，请重新查询。');A.revisions.opened=A.revisions.selected;},
 'connection-read':()=>API.readConnections(),'connection-next':()=>{A.connections.offset+=3;return API.readConnections(false);},'connection-open':el=>{const row=A.connections.page.items.find(x=>x.connectionId===el.dataset.auConnection);A.test.draft.endpoint=row.endpoint;A.test.draft.model=row.model;A.test.draft.credential=row.credentialPresent?{mode:'saved',connectionId:row.connectionId,version:row.version}:{mode:'none'};A.test.saved=clone(A.test.draft);A.test.savedVersion=row.version;window.DW_PROTOTYPE.go('connection-draft-test');},
 'test-start':()=>API.testConnection(progress()),'test-cancel':()=>{A.test.sequence++;A.test.pending=null;A.test.status='cancelled';A.test.result=null;A.test.message='测试已取消。';},'test-save':()=>{A.test.saved=clone(A.test.draft);A.test.savedVersion++;A.test.message='当前连接配置已保存为版本 '+A.test.savedVersion+'。';},
 'edit-submit':()=>API.submitEdit(progress()),'edit-cancel':()=>API.cancelEdit(),'edit-kind':el=>{A.edit.kind=el.dataset.auKind;A.edit.currentVersion=A.edit.kind==='image'?'3':'4';A.edit.plan=null;A.edit.result=null;A.edit.error='';},
 'content-submit':()=>API.submitContent(progress()),'content-cancel':()=>API.cancelContent()
};
const refresh=()=>window.DW_PROTOTYPE.go(A.current);
const progress=()=>{const id=A.current;return()=>{if(A.current===id)refresh();};};
V.authoring=s=>{A.current=s.id;return s.id.startsWith('variables')?variablesView(s):s.id.startsWith('revision')?revisionsView(s):s.id==='connection-browser'?connectionsView(s):s.id.startsWith('connection')?testView(s):s.id.startsWith('asset')?editView(s):contentView(s);};
const previousEditor=V.editor;V.editor=s=>previousEditor(s).replace('<span class="editor-version">',btn('历史版本','revision-browser','small')+btn('保存进度','content-save','small')+'<span class="editor-version">');
const previousRun=V.run;V.run=s=>previousRun(s).replace('<div class="row">','<div class="row">'+btn('检查变量','variables-inspect'));
const previousSettings=V.settings;V.settings=s=>previousSettings(s).replace('<div class="row">','<div class="row">'+btn('连接清单与草稿测试','connection-browser'));
for(const name of ['trajectory','template']){const old=V[name];if(old)V[name]=s=>old(s).replace('<div class="row">','<div class="row">'+btn('保存资产','asset-edit-save'));}
const previousCompletion=V.completion;V.completion=s=>previousCompletion(s).replace('<div class="row">','<div class="row">'+(s.id.startsWith('trajectory')||s.id.startsWith('capture')?btn('保存资产','asset-edit-save'):''));
const previousAssets=V.assets;V.assets=s=>previousAssets(s).replace('<div class="row">','<div class="row">'+btn('手工编辑保存','asset-edit-save'));
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-au-action]');if(!el||el.disabled)return;ev.preventDefault();ev.stopImmediatePropagation();const id=A.current,st=currentState();window.DW_AUTHORING_BUSY=(window.DW_AUTHORING_BUSY||0)+1;st.error='';try{await handlers[el.dataset.auAction]?.(el);}catch(e){st.error=e.message;st.message='';}if(A.current===id)refresh();window.DW_AUTHORING_BUSY--;},true);
document.addEventListener('change',ev=>{const el=ev.target,k=el.dataset.auField;if(!k)return;if(k==='var-frame'){A.variables.frameId=el.value==='主流程'?'frame-main':'frame-child';API.readVariables();}else if(k==='test-endpoint'||k==='test-model')API.changeTest(k==='test-endpoint'?'endpoint':'model',el.value);else if(k==='edit-destination'){A.edit.destination=el.value==='创建独立资产'?'create':'newVersion';A.edit.plan=null;A.edit.result=null;}else if(k==='edit-name'){A.edit.name=el.value;A.edit.plan=null;}refresh();});
window.DW_AUTHORING.afterRender=(_app,s)=>{if(s.view==='authoring')A.current=s.id;};
})();
